import type {EntryPointProps} from 'react-relay'

import type {branchExistsInBuildTypeQuery} from '../../../../../queries/__generated__/branchExistsInBuildTypeQuery.graphql'
import type {PermalinksQuery} from '../../../../common/Permalinks/__generated__/PermalinksQuery.graphql'
import type {TagsFiltersEntryPoint} from '../../../../common/TagsList/TagsFilters.entryPoint'

import type {BuildTypeHistoryQuery} from './__generated__/BuildTypeHistoryQuery.graphql'
import BuildTypeHistoryContainer from './BuildTypeHistory.container'
import type {BaseProps} from './BuildTypeHistory.types'

type Queries = {
  main: BuildTypeHistoryQuery
  permalinks: PermalinksQuery
  withBranches: branchExistsInBuildTypeQuery
}

type NestedEntryPoints = {
  tagsFilters: typeof TagsFiltersEntryPoint
}

export default function BuildTypeHistoryStandalone({
  queries,
  entryPoints,
  props,
}: EntryPointProps<Queries, NestedEntryPoints, BaseProps, {}>) {
  return (
    <BuildTypeHistoryContainer
      {...props}
      mainQuery={queries.main}
      permalinksQuery={queries.permalinks}
      withBranchesQueryRef={queries.withBranches}
      tagsFiltersEntryPoint={entryPoints.tagsFilters}
    />
  )
}

export type BuildTypeHistoryComponent = typeof BuildTypeHistoryStandalone
